        }
        @Override public void visitClassType(final String name) {
            if (genericName != null) {
                genericsMap.put(genericName, ' ' + name + ' ');
                genericName = null;
            }
            super.visitClassType(name);
        }
    };
    sr.accept(v);
    return genericsMap;
}

